(() => {'use strict';const R=HeroRules,$=id=>document.getElementById(id),g=()=>window.gameDebug;let heroes=[],draft=null,step=0,angle=0,saving=false,loaded=false;
const pick=n=>DND.die(n)-1,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function button(text,fn,cls=''){const b=document.createElement('button');b.type='button';b.textContent=text;if(window.UIIcons&&['‹','›','+','−','×'].includes(text)){b.replaceChildren(UIIcons.node(({'‹':'left','›':'right','+':'plus','−':'minus','×':'close'})[text]));}b.className=cls;b.onclick=fn;return b;}
function makeDraft(id='fighter'){return {name:['Арден','Рин','Мира','Бор'][pick(4)],classId:id,stats:R.preset(id),appearance:{skin:R.COLORS.skin[0],hair:R.COLORS.hair[0],cloth:R.COLORS.cloth[id==='wizard'?1:id==='fighter'?2:0],trim:R.COLORS.trim[0],hairStyle:'short',face:'soft'},kit:pick(2),background:R.background(id,pick)};}
async function api(method='GET',body,path=''){const r=await fetch('/api/heroes'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await r.json()}catch{throw Error('Сохранения недоступны. Попробуйте ещё раз.')}if(!r.ok)throw Error(data.error||'Ошибка сохранения.');return data;}
function show(){const d=$('heroes-panel');if(!d.open)d.showModal();}
function status(t){$('heroes-error').textContent=t;}
async function open(){show();if(draft){editor();return;}await list();}
async function list(){draft=null;step=0;$('heroes-title').textContent='Твои герои';$('heroes-body').replaceChildren();$('heroes-footer').replaceChildren();status('Загрузка героев…');try{const data=await api();heroes=data.heroes;loaded=true;status('');paintList();}catch(e){status(e.message);paintList();}}
function paintList(){const body=$('heroes-body');body.replaceChildren();if(!heroes.length){const p=document.createElement('p');p.className='subtle';p.textContent=loaded?'Создай первого героя. После подтверждения имя, внешность, класс и предыстория закрепятся.':'Список пока не загружен.';body.append(p);}for(const h of heroes){const card=document.createElement('article');card.className='saved-hero';const art=document.createElement('div');art.className='saved-hero-art';if(window.voxel?.heroPortrait)art.append(voxel.heroPortrait(h));const info=document.createElement('div'),title=document.createElement('h3'),sub=document.createElement('p');title.textContent=h.name;sub.textContent=R.CLASSES[h.classId].name+' · Человек · Уровень '+h.level+(h.activeWorldId?' · в приключении':'');info.append(title,sub);card.append(art,info,button('Миры · начать или продолжить',()=>window.Worlds.choose(h),'gold'),button('В тестовую комнату',()=>window.Worlds.enterTest(h)));const details=document.createElement('details');details.innerHTML='<summary>История и снаряжение</summary><p>'+esc(h.background)+'</p><p>'+h.inventory.map(esc).join(' · ')+'</p>';card.append(details,button('Удалить героя и его миры',()=>removeHero(h),'danger'));body.append(card);}const f=$('heroes-footer');f.replaceChildren(button('Создать героя',()=>start(false),'gold'),button('Быстрый старт',()=>start(true)),button('Обновить список',list));}
function removeHero(h){const d=$('modal');$('modal-title').textContent='Удалить героя?';const p=document.createElement('p');p.textContent='Герой «'+h.name+'» и все его миры будут удалены навсегда. Вернуть их нельзя.';$('modal-body').replaceChildren(p,button('Отмена',()=>d.close()),button('Удалить навсегда',async()=>{try{if(!await window.Worlds.prepareLeave())return;await api('DELETE',null,'/'+encodeURIComponent(h.id));if(g().state.party.some(p=>p.id===h.id)){window.Worlds.detach();g().test('reset');}d.close();await list();}catch(e){p.textContent=e.message;}},'danger'));d.showModal();}
function start(quick){draft=makeDraft();if(!quick)draft.stats=R.emptyStats();try{const cached=JSON.parse(sessionStorage.getItem('hero-draft'));if(cached){R.validate(cached);draft=cached;}}catch{}step=quick?3:0;angle=0;editor();}
function remember(){try{sessionStorage.setItem('hero-draft',JSON.stringify(draft))}catch{}}
function title(t){const h=document.createElement('h3');h.textContent=t;return h;}
function editor(){remember();status('');$('heroes-title').textContent='Новый герой';const body=$('heroes-body');body.replaceChildren();const steps=document.createElement('div');steps.className='creation-steps';['Основа','Характеристики','Внешность','История'].forEach((s,i)=>steps.append(button((i+1)+' · '+s,()=>{step=i;editor();},i===step?'active':'')));body.append(steps);const preview=document.createElement('div');preview.className='creation-preview';const figure=document.createElement('div');figure.id='creation-figure';preview.append(button('‹',()=>{angle=(angle+3)%4;paintPreview()},'rotate-hero'),figure,button('›',()=>{angle=(angle+1)%4;paintPreview()},'rotate-hero'));body.append(preview);
if(step===0){body.append(title('Имя и класс'));const label=document.createElement('label');label.textContent='Имя героя';const input=document.createElement('input');input.value=draft.name;input.maxLength=24;input.autocomplete='off';input.oninput=()=>{draft.name=input.value;remember();};label.append(input);body.append(label);const grid=document.createElement('div');grid.className='class-choices';for(const [id,c]of Object.entries(R.CLASSES))grid.append(button(c.name,()=>{draft.classId=id;draft.stats=R.preset(id);draft.kit=pick(2);draft.background=R.background(id,pick);draft.appearance.cloth=R.COLORS.cloth[id==='wizard'?1:id==='fighter'?2:0];editor();},draft.classId===id?'active':''));body.append(grid);const p=document.createElement('p');p.className='subtle';p.textContent='Человек · Уровень 1. '+R.CLASSES[draft.classId].hint;body.append(p);}
if(step===1){body.append(title('Распредели 27 очков'));const used=R.pointsUsed(draft.stats),remaining=R.POINT_BUDGET-used;const budget=document.createElement('p');budget.className='point-budget';budget.id='point-budget';budget.textContent='Осталось '+remaining+' из 27 · потрачено '+used;budget.setAttribute('role','status');body.append(budget);const p=document.createElement('p');p.className='subtle';p.textContent='Все характеристики начинают с 8. Значения 9–13 стоят по одному очку за повышение; 14 и 15 — по два. Это базовые значения до бонусов предыстории. '+R.CLASSES[draft.classId].hint;body.append(p);const grid=document.createElement('div');grid.className='point-stats';for(const [key,name]of Object.entries(R.LABELS)){const row=document.createElement('div');row.className='point-stat';const label=document.createElement('span');label.textContent=name;const value=document.createElement('strong');value.textContent=draft.stats[key];const modifier=document.createElement('small');const mod=DND.mod(draft.stats[key]);modifier.textContent='Модификатор '+(mod>=0?'+':'')+mod+' · стоимость '+R.POINT_COSTS[draft.stats[key]];const minus=button('−',()=>{if(R.adjustStat(draft.stats,key,-1))editor();});minus.dataset.stat=key;minus.dataset.delta='-1';minus.setAttribute('aria-label','Уменьшить: '+name);minus.disabled=draft.stats[key]<=8;const plus=button('+',()=>{if(R.adjustStat(draft.stats,key,1))editor();});plus.dataset.stat=key;plus.dataset.delta='1';plus.setAttribute('aria-label','Увеличить: '+name);plus.disabled=draft.stats[key]>=15||R.POINT_COSTS[draft.stats[key]+1]-R.POINT_COSTS[draft.stats[key]]>remaining;row.append(label,minus,value,plus,modifier);grid.append(row);}body.append(grid,button('Распределить под класс',()=>{draft.stats=R.preset(draft.classId);editor();}),button('Сбросить до 8',()=>{draft.stats=R.emptyStats();editor();}));}
if(step===2){body.append(title('Внешность'));for(const [key,name]of Object.entries({skin:'Кожа',hair:'Волосы',cloth:'Одежда',trim:'Отделка'})){const label=title(name),row=document.createElement('div');row.className='color-choices';R.COLORS[key].forEach((color,i)=>{const b=button('',()=>{draft.appearance[key]=color;editor();},draft.appearance[key]===color?'active':'');b.style.backgroundColor=color;b.setAttribute('aria-label',name+' · вариант '+(i+1));b.setAttribute('aria-pressed',String(draft.appearance[key]===color));row.append(b)});body.append(label,row);}for(const [key,name,options]of [['hairStyle','Причёска',{short:'Короткая',long:'Длинная',bald:'Без волос'}],['face','Лицо',{soft:'Мягкое',stern:'Суровое',beard:'С бородой'}]]){body.append(title(name));const row=document.createElement('div');row.className='class-choices';for(const [v,text]of Object.entries(options))row.append(button(text,()=>{draft.appearance[key]=v;editor();},draft.appearance[key]===v?'active':''));body.append(row);}}
if(step===3){body.append(title(draft.name+' · '+R.CLASSES[draft.classId].name));const p=document.createElement('p');p.textContent=draft.background;body.append(p,button('Новая предыстория',()=>{draft.background=R.background(draft.classId,pick);editor();}));body.append(title('Обычное стартовое снаряжение'));const kit=R.CLASSES[draft.classId].kits[draft.kit],ul=document.createElement('ul');kit.items.forEach(t=>{const li=document.createElement('li');li.textContent=t;ul.append(li)});body.append(ul,button('Другой комплект',()=>{draft.kit=(draft.kit+1)%R.CLASSES[draft.classId].kits.length;editor();}));const h=R.sheet({...draft,name:draft.name.trim()||'Герой'},'preview'),stats=document.createElement('p');stats.textContent='Очки характеристик '+R.pointsUsed(draft.stats)+' / 27 · Здоровье '+h.max+' · КД '+h.ac+' · '+Object.entries(draft.stats).map(([k,v])=>R.LABELS[k]+' '+v).join(' · ');body.append(stats);const note=document.createElement('p');note.className='creation-warning';note.textContent='После подтверждения имя, внешность, класс, начальные характеристики и предыстория закрепятся. Прокачка и смена снаряжения останутся доступны.';body.append(note);}
const f=$('heroes-footer');f.replaceChildren(button(step?'Назад':'К героям',()=>{if(step){step--;editor()}else{draft=null;$('heroes-title').textContent='Твои герои';paintList();}}));if(step<3)f.append(button('Далее',()=>{if(!draft.name.trim()){status('Введите имя героя.');return;}step++;editor();},'gold'));else{const b=button(saving?'Сохраняем…':'Подтвердить героя',confirm,'gold');b.disabled=saving||!draft.name.trim();f.append(b);}paintPreview();if(saving)$('heroes-panel').querySelectorAll('button,input,select').forEach(el=>el.disabled=true);}
function paintPreview(){const el=$('creation-figure');if(!el||!draft)return;el.replaceChildren();if(window.voxel?.heroPortrait){const h=R.sheet({...draft,name:draft.name.trim()||'Герой'},'preview');el.append(voxel.heroPortrait(h,angle));}else el.append(g().art(R.CLASSES[draft.classId].kind*4));}
async function confirm(){if(saving)return;try{R.validate(draft);if(R.pointsUsed(draft.stats)!==R.POINT_BUDGET){step=1;editor();status('Распределите оставшиеся '+(R.POINT_BUDGET-R.pointsUsed(draft.stats))+' очков перед подтверждением.');return;}saving=true;editor();const {hero}=await api('POST',draft);heroes.unshift(hero);draft=null;$('heroes-title').textContent='Твои герои';sessionStorage.removeItem('hero-draft');saving=false;status('Герой сохранён. Можно войти в тестовую комнату.');paintList();}catch(e){saving=false;editor();status(e.message);}}
function init(){const d=document.createElement('dialog');d.id='heroes-panel';d.className='heroes-panel';d.innerHTML='<div class="modal-head"><h2 id="heroes-title">Твои герои</h2><button id="heroes-close" aria-label="Закрыть">×</button></div><div id="heroes-body"></div><p id="heroes-error" role="status" aria-live="polite"></p><div id="heroes-footer"></div>';document.body.append(d);$('heroes-close').onclick=()=>{if(!saving&&!window.Worlds.atMenu)d.close()};d.addEventListener('cancel',e=>{if(saving||window.Worlds.atMenu)e.preventDefault()});const b=button('Мои герои',open);b.id='saved-heroes-open';$('hero-view').prepend(b);open();}
window.Heroes={init,open,paintPreview,refreshPortraits:()=>{if(draft)paintPreview();else if(loaded)paintList();},get heroes(){return heroes},get draft(){return draft},start,confirm};})();
